ures": {"reps": 1, "label": "new", "score": 3, "shops": 1, "visits": 2, "overdue": false, "baseline": 0.0, "insights": 2, "severity": "high", "age_weeks": 0, "open_shops": 1, "last_seen_at": "2026-10-31T12:52:45Z", "raised_again": 1, "seen_periods": 0}, "title_en": "Schemes and promotions · Lay's display rack payment · Northgate Agencies"}, {"status": "open", "category": "schemes", "issue_id": "5d157be7-8c10-4d7a-9b99-544d79b50240", "measures": {"reps": 1, "label": "new", "score": 2, "shops": 1, "visits": 2, "overdue": false, "baseline": 0.0, "insights": 2, "severity": "medium", "age_weeks": 0, "open_shops": 1, "last_seen_at": "2026-10-31T11:38:16Z", "raised_again": 1, "seen_periods": 0}, "title_en": "Schemes and promotions · Riverbend Traders"}, {"status": "open", "category": "payments", "issue_id": "6a98f023-24ac-421c-94cb-14b921061167", "measures": {"reps": 1, "label": "new", "score": 2, "shops": 1, "visits": 1, "overdue": false, "baseline": 0.0, "insights": 1, "severity": "medium", "age_weeks": 0, "open_shops": 1, "last_seen_at": "2026-10-31T11:38:16Z", "raised_again": 0, "seen_periods": 0}, "title_en": "Credit and payments · Riverbend Traders"}, {"status": "open", "category": "schemes", "issue_id": "abfb64fa-2081-451c-8aaa-931cdf69bb8c", "measures": {"reps": 1, "label": "new", "score": 2, "shops": 1, "visits": 1, "overdue": false, "baseline": 0.0, "insights": 1, "severity": "medium", "age_weeks": 0, "open_shops": 1, "last_seen_at": "2026-10-31T07:54:49Z", "raised_again": 0, "seen_periods": 0}, "title_en": "Schemes and promotions · Northgate Agencies"}, {"status": "open", "category": "schemes", "issue_id": "828867a4-4a72-4283-b3a4-3cc7ea31e3ee", "measures": {"reps": 1, "label": "new", "score": 2, "shops": 1, "visits": 1, "overdue": false, "baseline": 0.0, "insights": 1, "severity": "medium", "age_weeks": 0, "open_shops": 1, "last_seen_at": "2026-10-30T05:44:28Z", "raised_again": 0, "seen_periods": 0}, "title_en": "Schemes and promotions · Station Road Distributo